<h2>Estimate depth of field</h2><p class="lead">Calculate hyperfocal, near-focus and far-focus limits from focal length, aperture, focus distance and circle of confusion.</p><div class="notice">This is a geometric depth-of-field estimate, not a guarantee of perceived sharpness. Diffraction, lens performance, focus accuracy and final viewing conditions also matter.</div><div class="form-grid"><div class="field"><label for="f">Focal length (mm)</label><input id="f" type="number" value="50" min="1" step="any"></div><div class="field"><label for="n">Aperture (f-number)</label><input id="n" type="number" value="2.8" min="0.5" step="any"></div><div class="field"><label for="s">Focus distance (m)</label><input id="s" type="number" value="3" min="0.01" step="any"></div><div class="field"><label for="c">Circle of confusion (mm)</label><input id="c" type="number" value="0.03" min="0.001" step="any"><small class="helper">0.030 mm is a common full-frame planning value; use a value appropriate to your format and output.</small></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Hyperfocal distance</span><strong id="hyper">—</strong></div><div class="metric"><span>Near limit</span><strong id="near">—</strong></div><div class="metric"><span>Far limit</span><strong id="far">—</strong></div><div class="metric"><span>Total depth of field</span><strong id="dof">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('hyper').textContent='—';$('near').textContent='—';$('far').textContent='—';$('dof').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const f=num('f'),N=num('n'),sm=num('s'),c=num('c');if(!(f>0&&N>0&&sm>0&&c>0))throw 0;const s=sm*1000;const H=f*f/(N*c)+f;const near=H*s/(H+(s-f));let far=Infinity;if(H>(s-f))far=H*s/(H-(s-f));$('hyper').textContent=fmt(H/1000,2)+' m';$('near').textContent=fmt(near/1000,2)+' m';$('far').textContent=Number.isFinite(far)?fmt(far/1000,2)+' m':'∞';$('dof').textContent=Number.isFinite(far)?fmt((far-near)/1000,2)+' m':'From '+fmt(near/1000,2)+' m to ∞';$('note').textContent='Depth of field is an optical planning estimate. Circle of confusion depends on format, viewing size, viewing distance and sharpness expectations.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
